class Solution {
public:
    string toHexspeak(string num) {
        unsigned long long value = stoull(num);
        const string hex = "0123456789ABCDEF";
        string answer;
        while (value > 0) {
            int digit = value % 16;
            if (digit >= 2 && digit <= 9) {
                return "ERROR";
            }
            answer.push_back(digit == 0 ? 'O' : (digit == 1 ? 'I' : hex[digit]));
            value /= 16;
        }
        reverse(answer.begin(), answer.end());
        return answer;
    }
};
